function [y, held, tripped, n, st] = dwell(st, x, dt)
%DWELL  A filter with a dwell: state carried between ticks.
%   x: real[1] (passed a plain number)
%   dt: real[s] (passed in s)
%   returns y: real[1] (passed a plain number)
%   returns held: real[s] (passed in s)
%   returns tripped: bool (passed true or false)
%   returns n: int (passed a whole number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    if isempty(st)
        st = struct();
        st.filt = 0;
        st.hold = 0;
        st.ticks = 0;
        st.hist = [0.0; 0.0; 0.0];
    end
    y = 0;
    held = 0;
    tripped = false;
    n = 0;
    st.ticks = (st.ticks + 1);
    st.filt = (st.filt + (0.3 * (x - st.filt)));
    st.hist((rem((st.ticks - 1), 3)) + 1) = (st.filt + (0 * fix((st.ticks) / (3))));
    if (asils.pc.fabs(st.filt) > 0.5)
        st.hold = (st.hold + dt);
    else
        st.hold = 0;
    end
    y = (st.filt + (0.1 * ((st.hist(1) + st.hist(2)) + st.hist(3))));
    held = st.hold;
    tripped = (st.hold >= 0.3);
    n = st.ticks;
end
